import os
from moler.device import DeviceFactory
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl


@load_moler_configuration_from_tl()
def convert_pcap_to_xml(pcap_file, xml_file=None, options=None, timeout=5 * 60):
    """
    Convert pcap file to xml format using pdml format

    :param pcap_file:   path to source pcap_file
    :param xml_file:    path to destination xml file
    :param options:     additional options used in conversion, eg -Y SCTP
    :param timeout:     conversion timeout
    """

    local_pc = DeviceFactory.get_device(name='UnixLocal')

    if not xml_file:
        file_name = os.path.splitext(pcap_file)[0]
        xml_file = "{}.xml".format(file_name)

    if options:
        cmd_options = "-r {} -T pdml {} > {}".format(pcap_file, options, xml_file)
    else:
        cmd_options = "-r {} -T pdml > {}".format(pcap_file, xml_file)
    convert = local_pc.get_cmd(cmd_name="tshark", cmd_params={'options': cmd_options})
    convert(timeout=timeout)

    return xml_file


@load_moler_configuration_from_tl()
def convert_pcap_to_csv(pcap_file, csv_file=None, fields=None, filters=None, options=None, timeout=5 * 60):
    """
    Convert pcap file to csv format.

    :param pcap_file:   path to source pcap_file
    :param csv_file:    path to destination csv file
    :param fields:      list of fields - option -e
    :param filters:     list of filters - option -Y
    :param options:     additional options used in conversion, eg -Y SCTP
    :param timeout:     conversion timeout
    """
    local_pc = DeviceFactory.get_device(name='UnixLocal')

    if not csv_file:
        file_name, extension = os.path.splitext(pcap_file)
        csv_file = "{}_{}.csv".format(file_name, extension.lstrip('.'))

    tshark_options = "-E header=y -E separator=, -E quote=d -E occurrence=f"

    if fields:
        field_options = ' -T fields -e {}'.format(' -e '.join(fields))
        tshark_options = tshark_options + field_options

    if filters:
        filters_options = ' -Y "{}"'.format(' || '.join(filters))
        tshark_options = tshark_options + filters_options

    if options:
        tshark_options = tshark_options + ' ' + options

    cmd_options = "-r {} {} > {}".format(pcap_file, tshark_options, csv_file)
    convert = local_pc.get_cmd(cmd_name="tshark", cmd_params={'options': cmd_options})
    convert(timeout=timeout)

    return csv_file


@load_moler_configuration_from_tl()
def convert_all_pcaps_in_directory(directory_path, conversion_type='xml', options=None):
    converter = _get_converter_type(conversion_type)
    local_pc = DeviceFactory.get_device(name='UnixLocal')
    ls = local_pc.get_cmd(cmd_name="ls", cmd_params={'path': os.path.join(directory_path, '*.pcap')})
    pcap_files = ls()['files']

    for pcap_file_name in pcap_files:
        pcap_file_path = os.path.join(directory_path, pcap_file_name)
        converter(pcap_file=pcap_file_path, options=options)


def _get_converter_type(conversion_type):
    if conversion_type == 'xml':
        converter = convert_pcap_to_xml
    elif conversion_type == 'csv':
        converter = convert_pcap_to_csv
    else:
        raise ValueError("Incorrect conversion type! Passed {} - possible values'xml', 'csv'".format(conversion_type))

    return converter


@load_moler_configuration_from_tl()
def convert_pcap_by_luascript_to_csv(pcap_file, csv_file=None, fields=None, filters=None, options=None,
                                     lua_script='/opt/luashark/luashark.lua', timeout=10 * 60):
    """
    Convert pcap file to xml format using pdml format

    :param pcap_file:      path to source pcap_file
    :param csv_file:       path to destination csv file
    :param fields:      list of fields - option -e
    :param filters:     list of filters - option -Y
    :param options:        additional options used in conversion, eg -Y SCTP
    :param lua_script:     path to luashark script
    :param timeout:        conversion timeout
    """
    lua_options = '-X lua_script:{}'.format(lua_script)

    if options:
        lua_options = "{} {}".format(lua_options, options)

    convert_pcap_to_csv(pcap_file, csv_file,
                        fields=fields, filters=filters, options=lua_options, timeout=timeout)

    return csv_file
